package com.bank.reg.store;

import com.bank.reg.model.CustomerRow;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

// Simulates a table. "enforced" = true mimics a DB UNIQUE constraint.
public class CustomerStore {
    private final List<CustomerRow> rows = Collections.synchronizedList(new ArrayList<>());
    private final AtomicLong seq = new AtomicLong();
    private final boolean enforced;
    public CustomerStore(boolean enforced) { this.enforced = enforced; }

    public boolean existsByEmail(String email) {
        String key = norm(email);
        synchronized (rows) {
            return rows.stream().anyMatch(r -> norm(r.getEmail()).equals(key));
        }
    }

    // Atomic enforced insert — like the DB rejecting a duplicate at write time.
    public synchronized void insert(String email) {
        if (enforced && existsByEmail(email)) {
            throw new IllegalStateException("UNIQUE violation: " + email); // DB would throw
        }
        rows.add(new CustomerRow(seq.incrementAndGet(), email));
    }

    // Non-atomic insert used by the BROKEN check-then-insert path.
    public void insertNoCheck(String email) { rows.add(new CustomerRow(seq.incrementAndGet(), email)); }

    public List<CustomerRow> findAll() { synchronized (rows) { return new ArrayList<>(rows); } }
    private static String norm(String e) { return e.trim().toLowerCase(); }
}
