package com.bank.reg.service;

import com.bank.reg.store.CustomerStore;
import java.util.logging.Logger;

public class RegistrationService {
    private static final Logger log = Logger.getLogger(RegistrationService.class.getName());
    private final CustomerStore store;
    public RegistrationService(CustomerStore store) { this.store = store; }

    // BROKEN: check-then-insert has a race window between check and insert.
    public void registerCheckThenInsert(String email) {
        if (!store.existsByEmail(email)) {        // step 1 (both threads see "false")
            sleep();                               // widen the race window
            store.insertNoCheck(email);            // step 2 (both insert → duplicate)
        }
    }

    // SAFE: let the DB enforce; catch the violation for a friendly message.
    public void registerEnforced(String email) {
        try {
            store.insert(email);                   // atomic enforced insert
        } catch (IllegalStateException dup) {
            log.warning(() -> "Rejected duplicate email (friendly message): " + email);
        }
    }

    private void sleep() { try { Thread.sleep(20); } catch (InterruptedException ignored) {} }
}
