package com.bank.reg.service;

import com.bank.reg.model.CustomerRow;
import com.bank.reg.store.CustomerStore;
import java.util.*;

public class DuplicateFinder {
    private final CustomerStore store;
    public DuplicateFinder(CustomerStore store) { this.store = store; }

    // GROUP BY LOWER(TRIM(email)) HAVING COUNT(*) > 1
    public Map<String, Long> duplicates() {
        Map<String, Long> counts = new LinkedHashMap<>();
        for (CustomerRow r : store.findAll()) {
            counts.merge(r.getEmail().trim().toLowerCase(), 1L, Long::sum);
        }
        Map<String, Long> dupes = new LinkedHashMap<>();
        counts.forEach((k, v) -> { if (v > 1) dupes.put(k, v); });
        return dupes;
    }
}
