package com.bank.reg;

import com.bank.reg.service.DuplicateFinder;
import com.bank.reg.service.RegistrationService;
import com.bank.reg.store.CustomerStore;

public class RegistrationApplication {
    public static void main(String[] args) throws InterruptedException {
        // 1) BROKEN store (no DB constraint): two threads race the same email
        CustomerStore broken = new CustomerStore(false);
        RegistrationService svc = new RegistrationService(broken);
        Runnable r = () -> svc.registerCheckThenInsert("rajesh@x.com");
        Thread t1 = new Thread(r), t2 = new Thread(r);
        t1.start(); t2.start(); t1.join(); t2.join();
        System.out.println("BROKEN store rows: " + broken.findAll().size() + " (expected 1, race made 2)");
        System.out.println("Duplicates found: " + new DuplicateFinder(broken).duplicates());

        // 2) ENFORCED store (DB UNIQUE): second insert rejected
        CustomerStore enforced = new CustomerStore(true);
        RegistrationService svc2 = new RegistrationService(enforced);
        svc2.registerEnforced("rajesh@x.com");
        svc2.registerEnforced("rajesh@x.com"); // rejected by constraint
        System.out.println("ENFORCED store rows: " + enforced.findAll().size() + " (always 1)");
    }
}
